let interessados = 0;
const botao = document.querySelector("#adicionar");
const saida = document.querySelector("#total");
function renderizar() {
  if (saida) saida.textContent = String(interessados);
}
if (botao) botao.addEventListener("click", () => {
  interessados += 1;
  renderizar();
});

const reiniciar = document.querySelector("#reiniciar");
if (reiniciar) reiniciar.addEventListener("click", () => {
  interessados = 0;
  renderizar();
});

def somar_atrasos(dias):
    total = 0
    for atraso in dias:
        if atraso > 0:
            total += atraso
    return total
print(somar_atrasos([0, 2, 3]))

def contar_atrasados(dias):
    quantidade = 0
    for atraso in dias:
        if atraso > 0:
            quantidade += 1
    return quantidade
print(contar_atrasados([0, 2, 3]))

function criarCartao(oficina) {
  const artigo = document.createElement("article");
  artigo.className = "cartao";
  const titulo = document.createElement("h2");
  titulo.textContent = oficina.nome;
  const vagas = document.createElement("p");
  vagas.textContent = `${oficina.vagas} vagas disponíveis`;
  artigo.append(titulo, vagas);
  return artigo;
}

const oficinas = [{ nome: "Leitura", vagas: 0 }, { nome: "Escrita", vagas: 5 }];
const lista = document.querySelector("#oficinas");
if (lista) {
  const cartoes = oficinas.map(criarCartao);
  lista.replaceChildren(...cartoes);
}

