function validarOficina(dado) {
  if (!dado || typeof dado !== "object" || Array.isArray(dado)) throw new Error("Objeto esperado");
  if (typeof dado.id !== "string" || !dado.id.trim()) throw new Error("id inválido");
  if (typeof dado.nome !== "string" || !dado.nome.trim()) throw new Error("nome inválido");
  if (!Number.isInteger(dado.vagas) || dado.vagas < 0) throw new Error("vagas inválidas");
  return { id: dado.id, nome: dado.nome.trim(), vagas: dado.vagas };
}

const recebido = { id: "of-1", nome: " Leitura ", vagas: 0 };
console.log(validarOficina(recebido));
try {
  validarOficina({ id: "of-2", nome: "Escrita", vagas: "5" });
} catch (erro) {
  console.error(erro.message);
}

